    [23060]={name="Bonescythe Ring",quality=4,ilvl=92,reqLevel=60,sourceType="boss_drop",instructions="Drops from Kel'Thuzad.",zone="Naxxramas",npc="Kel'Thuzad",lore="Once an archmage of the Kirin Tor, he left Dalaran to found the Cult of the Damned and served Ner'zhul willingly. Killed at Andorhal and raised as a lich, he rules Naxxramas from a phylactery at its heart."},
    [23323]={name="Crown of the Fire Festival",quality=1,ilvl=1,sourceType="quest_reward",instructions="Reward from the quest 'A Thief's Reward'.",questName="A Thief's Reward",seasonal=true,lore="This flame, stolen from the heart of Stormwind itself, floods you with warmth. This raw power is foreign to you, but the (NAME) might know more..."},
